"""Shared test helpers. Test PDFs are generated by code, so no binary files are committed."""

from collections.abc import Callable
from pathlib import Path

import pymupdf
import pytest

from insureassist.config import Settings, settings


@pytest.fixture(autouse=True)
def default_settings(monkeypatch: pytest.MonkeyPatch) -> None:
    """Every test starts from the built-in defaults, NOT from the developer's .env file
    or environment variables. Otherwise e.g. VECTOR_STORE=qdrant in .env would make tests
    talk to a real Qdrant server. Tests that need another value set it explicitly."""
    defaults = Settings.model_construct()  # defaults only: no .env, no environment
    for name in Settings.model_fields:
        monkeypatch.setattr(settings, name, getattr(defaults, name))


def _write_pdf(path: Path, page_texts: list[str]) -> Path:
    doc = pymupdf.open()
    for text in page_texts:
        page = doc.new_page()
        if text:
            page.insert_text((72, 72), text)
    doc.save(path)
    doc.close()
    return path


@pytest.fixture
def make_pdf(tmp_path: Path) -> Callable[..., Path]:
    """Create a PDF with one page per string: make_pdf(["page 1 text", "page 2 text"])."""

    def factory(page_texts: list[str], name: str = "sample.pdf") -> Path:
        return _write_pdf(tmp_path / name, page_texts)

    return factory


@pytest.fixture
def image_only_pdf(tmp_path: Path) -> Path:
    """A one-page PDF containing only a full-page image, like a scanned document."""
    doc = pymupdf.open()
    page = doc.new_page()
    pixmap = pymupdf.Pixmap(pymupdf.csRGB, pymupdf.IRect(0, 0, 50, 50), False)
    pixmap.clear_with(200)  # light grey picture
    page.insert_image(page.rect, pixmap=pixmap)
    path = tmp_path / "scanned.pdf"
    doc.save(path)
    doc.close()
    return path
